package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaEsDraft2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_yamani_hajar" to DuaText("Entre Rukn Yamani y Hajar Aswad", "Señor nuestro, danos el bien en este mundo y el bien en el Más Allá, y protégenos del castigo del Fuego.", "En tawaf, entre el Rincón Yemení y la Piedra Negra.", "El Profeta ﷺ recitó esto en este lugar del tawaf."),
        "dua_safa_marwa" to DuaText("En Safa y Marwa", "Nadie tiene derecho a ser adorado excepto Allah, solo, sin asociado. Suyo es el dominio y suya la alabanza, y tiene poder sobre todas las cosas. Nadie tiene derecho a ser adorado excepto Allah únicamente; Cumplió su promesa, ayudó a su siervo y solo derrotó a los confederados.", "Subiendo a Safa y enfrentándose a la Qiblah (tres veces).", "El dhikr del Profeta ﷺ en Safa y Marwah."),
        "dua_arafah" to DuaText("Mejor Dua del Día de Arafah", "Nadie tiene derecho a ser adorado excepto Allah, solo, sin asociado. Suyo es el dominio y suya la alabanza, y tiene poder sobre todas las cosas.", "El Día de Arafah: la mejor dua.", "La mejor dua es la dua del Día de Arafah, y las mejores palabras son estas."),
        "dua_takbeer_tashreeq" to DuaText("Takbeer-e-Tashreeq", "Allah es el Más Grande, Allah es el Más Grande. No hay más dios que Alá. Allah es el Más Grande, Allah es el Más Grande y toda alabanza es para Allah.", "Después de cada oración obligatoria desde el Fajr del 9 de Dhul-Hijjah hasta el Asr del 13 de Dhul-Hijjah.", "Reportado por Ali e Ibn Mas'ud (RA) - wajib según los Hanafis."),
        "dua_zamzam" to DuaText("Bebiendo zamzam", "Oh Allah, te pido conocimiento beneficioso, provisión abundante y una cura para toda enfermedad.", "Cuando bebas Zamzam, haz dua para lo que sea que te propongas.", "Zamzam es para cualquier cosa que se beba (Ibn Majah 3062)."),
        "dua_q_ma_khalaqta_batila" to DuaText("Reflexionando sobre la creación", "Señor nuestro, no creaste todo esto en vano. Gloria a Ti, protégenos del castigo del Fuego.", "La dua de quienes reflexionan sobre la creación de los cielos y la tierra.", "La dua de las personas comprensivas (ulul-albab)."),
        "dua_q_sami_na_munadiyan" to DuaText("Escuchamos al llamador a la fe", "Señor nuestro, escuchamos a un llamador que llamaba a la fe, diciendo: \"Cree en tu Señor\", y creímos. Señor nuestro, perdónanos nuestros pecados, quita de nosotros nuestras malas acciones y haz que muramos con los justos.", "Una dua por la fe y la muerte entre los justos.", "Un dua por el perdón y un buen final."),
        "dua_q_atina_ma_waadtana" to DuaText("Concédenos lo que prometiste", "Señor nuestro, concédenos lo que nos prometiste a través de Tus Mensajeros y no nos deshonres en el Día de la Resurrección. De hecho, Tú no incumples Tu promesa.", "Refugio de la desgracia en el Día de la Resurrección.", "Buscando honor en el Más Allá."),
        "dua_q_israfana" to DuaText("Perdona nuestros excesos", "Señor nuestro, perdónanos nuestros pecados y nuestros excesos en nuestros asuntos, haz nuestros pies firmes y ayúdanos contra los incrédulos.", "La dua de los compañeros de Profetas anteriores.", "Un dua por la firmeza y el perdón."),
        "dua_q_jamiun_nas" to DuaText("Reunirás a la humanidad", "Señor nuestro, seguramente reunirás a la humanidad en un Día del que no hay duda. De hecho, Allah no incumple Su promesa.", "Afirmando certeza en el Día de la Resurrección.", "La dua de aquellos firmemente arraigados en el conocimiento."),
        "dua_q_maash_shahidin" to DuaText("Escríbanos entre los testigos", "Señor nuestro, hemos creído, escríbenos entre los testigos.", "La dua de quienes reconocieron la verdad y creyeron.", "Un dua para la aceptación de la propia fe."),
        "dua_q_la_tajalna_zalimin" to DuaText("No con los malhechores", "Señor nuestro, no nos pongas con la gente que hace el mal.", "La dua del pueblo de al-A'raf.", "Refugio del destino de los malhechores."),
        "dua_q_tawaffana_muslimin" to DuaText("Paciencia y muerte como musulmanes", "Señor nuestro, derrama paciencia sobre nosotros y haz que muramos como musulmanes.", "La dua de los magos del faraón cuando creyeron.", "Paciencia en la prueba y final en la fe."),
        "dua_q_la_tajalna_fitnah" to DuaText("No es un juicio para los opresores", "En Allah confiamos. Señor nuestro, no nos hagas una prueba para los malvados, y sálvanos con tu misericordia de los incrédulos.", "La dua del pueblo de Musa (AS).", "Una dua para el rescate de la opresión y los opresores."),
        "dua_q_nuh_ma_laysa_li" to DuaText("Dua de Nuh (AS) para el perdón", "Señor mío, en Ti me refugio para no pedirte aquello de lo que no tengo conocimiento. Y a menos que me perdones y tengas misericordia de mí, estaré entre los perdedores.", "La dua del arrepentimiento del Profeta Nuh (AS).", "Una lección sobre cómo preguntar con buenos modales."),
        "dua_q_mudkhala_sidq" to DuaText("Entrada y salida de la verdad", "Señor mío, hazme entrar con la verdad y salir con la verdad, y concédeme de Ti una autoridad sustentadora.", "Antes de ingresar a una nueva tarea, hogar o lugar.", "La dua le enseñó al Profeta ﷺ en la época de la Hégira."),
        "dua_q_la_tadharni_fardan" to DuaText("Dua de Zakariya (AS) - No me dejes solo", "Señor mío, no me dejes solo, y Tú eres el mejor de los herederos.", "Para quienes buscan niños.", "A través de esta dua Allah concedió a Yahya (AS)."),
        "dua_q_munzalan_mubarakan" to DuaText("Un lugar de aterrizaje bendito", "Mi Señor, déjame aterrizar en un lugar de aterrizaje bendito, y Tú eres el mejor de los que traes a tierra.", "Cuando se muda a una nueva casa o se detiene en algún lugar, la dua de Nuh (AS).", "Una dua de bendición en un lugar nuevo."),
        "dua_q_amanna_faghfir" to DuaText("Creemos, así que perdónanos", "Señor nuestro, hemos creído, perdónanos y ten piedad de nosotros, y Tú eres el mejor de los misericordiosos.", "La dua de los siervos justos de Allah.", "Una dua integral por el perdón y la misericordia."),
        "dua_q_isrif_jahannam" to DuaText("Evitar el castigo del infierno", "Señor nuestro, aparta de nosotros el castigo del infierno; de hecho, su castigo es siempre persistente. De hecho, es un asentamiento y una residencia malvados.", "La dua de los siervos del Más Misericordioso ('Ibad ar-Rahman).", "Una dua coránica para refugiarse del infierno."),
        "dua_q_hab_li_hukman" to DuaText("Dua de Ibrahim (AS) — Sabiduría y Jannah", "Mi Señor, concédeme sabiduría y únete a los justos, concédeme una mención honorable entre las generaciones futuras y hazme entre los herederos del Jardín de la Bienaventuranza.", "Pidiendo sabiduría, la compañía de los justos y el Paraíso.", "Una dua completa de Ibrahim (AS)."),
        "dua_q_lut_najjini_ahli" to DuaText("Dua de Lut (AS) — Salva a mi familia", "Mi Señor, sálvame a mí y a mi familia de (la consecuencia de) lo que hacen.", "Proteger a la propia familia de un entorno de maldad.", "Protección de la familia del mal."),
        "dua_q_sulaiman_awzini" to DuaText("Dua de Sulaiman (AS) para la gratitud", "Mi Señor, permíteme estar agradecido por Tu favor que nos otorgaste a mí y a mis padres, y hacer obras justas que te agraden, y admitirme por Tu misericordia entre Tus siervos justos.", "Por la capacidad de agradecer las bendiciones.", "El dua de gratitud de Sulayman (AS)."),
        "dua_q_musa_zalamtu" to DuaText("Dua de Musa (AS) — Me hice daño a mí mismo", "Mi Señor, me he hecho daño a mí mismo, así que perdóname.", "Arrepentimiento inmediato después de un error.", "Allah perdonó a Musa (AS)."),
        "dua_q_musa_najjini" to DuaText("Dua de Musa (AS) — Sálvame de los opresores", "Señor mío, sálvame de la gente malvada.", "Al temer a los opresores.", "La dua de Musa (AS) al salir de Egipto."),
        "dua_q_lut_unsurni" to DuaText("Dua de Lut (AS) — Ayuda contra los corruptores", "Señor mío, ayúdame contra la gente corruptora.", "Por ayuda contra quienes propagan la corrupción.", "La dua de quienes se mantienen firmes en la verdad."),
        "dua_q_hab_li_salihin" to DuaText("Dua de Ibrahim (AS) para un niño justo", "Señor mío, concédeme (un niño) de entre los justos.", "Pidiendo hijos justos.", "A través de esta dua Isma'il se concedió (AS)."),
        "dua_q_wasita_kulla_shay" to DuaText("Dua de los ángeles que llevan el trono", "Señor nuestro, Tú abarcas todas las cosas en misericordia y conocimiento, así que perdona a aquellos que se arrepienten y siguen Tu camino, y protégelos del castigo del infierno.", "Los ángeles que llevan el Trono hacen esta dua para los creyentes.", "Recitado con la intención de ser incluido en el dua de los ángeles."),
        "dua_q_ikhwanina" to DuaText("Por nuestros hermanos que nos precedieron", "Señor nuestro, perdónanos a nosotros y a nuestros hermanos que nos precedieron en la fe, y no pongas rencor en nuestros corazones hacia los que creen. Señor nuestro, en verdad eres bondadoso y misericordioso.", "Una dua para los creyentes que vinieron antes y para un corazón limpio.", "Una dua para los nobles Compañeros (RA) y los primeros creyentes."),
        "dua_q_alayka_tawakkalna" to DuaText("En ti confiamos (Ibrahim AS)", "Señor nuestro, en Ti confiamos, a Ti nos dirigimos y a Ti es el retorno. Señor nuestro, no nos hagas prueba para los incrédulos y perdónanos. Señor nuestro, Tú eres en verdad el Todopoderoso, el Sabio.", "La dua de Ibrahim (AS) y sus compañeros.", "Un dua de confianza en Allah y volverse hacia Él."),
        "dua_q_atmim_nurana" to DuaText("Perfecciona nuestra luz", "Señor nuestro, perfecciona para nosotros nuestra luz y perdónanos. De hecho, tienes poder sobre todas las cosas.", "La dua de los creyentes en el Día de la Resurrección.", "Pidiendo luz sobre el Sirat."),
        "dua_q_asiya_baytan" to DuaText("Dua de Asiya: una casa en Jannah", "Señor mío, constrúyeme cerca de Ti una casa en el Paraíso, sálvame del Faraón y sus obras, y sálvame de la gente malvada.", "La dua de Asiya, la esposa del faraón.", "Allah la hizo un ejemplo para los creyentes."),
        "dua_adhan_response" to DuaText("Respondiendo al Adhan", "No hay fuerza ni poder excepto en Allah.", "Repite lo que dice el muecín; en 'Hayya 'alas-salah' y 'Hayya 'alal-falah' dicen esto.", "Quien responda desde el corazón entrará al Paraíso."),
        "dua_adhan_shahadah" to DuaText("Después de la Shahadah de los muazines", "Y yo también doy testimonio de que nadie tiene derecho a ser adorado excepto Allah, solo, sin asociado, y que Muhammad ﷺ es Su siervo y Mensajero. Estoy complacido con Allah como Señor, con Muhammad ﷺ como Mensajero y con el Islam como religión.", "Al escuchar el testimonio de fe del muecín.", "Sus pecados son perdonados."),
        "dua_istiftah_baid" to DuaText("Dua de apertura: Aléjame de los pecados", "Oh Allah, aléjame de mis pecados como has distanciado el este del oeste. Oh Allah, límpiame de los pecados como una prenda blanca se limpia de la suciedad. Oh Allah, lava mis pecados con agua, nieve y granizo.", "Después del takbir de apertura (también se puede decir en lugar del Sana).", "El Profeta ﷺ recitó esto entre el takbir y la recitación."),
        "dua_hamdan_kathiran" to DuaText("Abundantes elogios después de Ruku", "Señor nuestro, a Ti pertenece la alabanza: alabanza abundante, pura y bendita.", "Después de surgir del ruku, junto con 'Rabbana lakal-hamd'.", "Más de treinta ángeles corrían para ser los primeros en registrarlo."),
        "dua_subbuhun_quddus" to DuaText("Subbuhun Quddus (Ruku y Sujood)", "(Alá es) Muy Glorificado, Santísimo, Señor de los ángeles y del Espíritu (Jibril).", "En ruku y sujood.", "El Profeta ﷺ recitó esto en ruku y sujood."),
        "dua_sujood_dhanbi_kullah" to DuaText("En Sujood: Perdona todos mis pecados", "Oh Allah, perdóname todos mis pecados: los pequeños y los grandes, los primeros y los últimos, los abiertos y los ocultos.", "En buen estado.", "La postración es un lugar donde se responden las duas."),
        "dua_sujood_ridaka" to DuaText("Refugiate en tu placer", "Oh Allah, me refugio en Tu complacencia de Tu ira, en Tu perdón de Tu castigo, y me refugio en Ti de Ti. No puedo alabarte plenamente; Eres como te has alabado a ti mismo.", "En suyud, Aisha (RA) escuchó al Profeta ﷺ decir esto.", "Un sujood dua del Profeta ﷺ."),
        "dua_tashahhud" to DuaText("Tashahhud (At-Tahiyyat)", "Todos los actos de adoración verbales, físicos y financieros son para Allah. La paz sea contigo, oh Profeta, y la misericordia de Allah y Sus bendiciones. La paz sea con nosotros y con los justos servidores de Allah. Doy testimonio de que nadie tiene derecho a ser adorado excepto Allah, y doy testimonio de que Muhammad ﷺ es Su siervo y Mensajero.", "En cada sesión, narrado por Abdullah ibn Mas'ud (RA) (la práctica Hanafi).", "El Profeta ﷺ lo enseñó como una sura del Corán."),
    )
}
